 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row}

    # The separator is the color forming repeated near-uniform lines in both axes.
    candidates = []
    for color in colors:
        rows = [r for r in range(h) if sum(x == color for x in grid[r]) >= 0.80 * w]
        cols = [c for c in range(w) if sum(grid[r][c] == color for r in range(h)) >= 0.80 * h]
        if rows and cols:
            candidates.append((len(rows) + len(cols), color, rows, cols))
    if not candidates:
        raise ValueError('separator not found')
    _, sep, rows, cols = min(candidates)

    # Find embedded rectangular lattice region: active separator rows/cols are
    # those with colored intersections; then use their spacing pattern.
    marked_rows = [r for r in rows if any(grid[r][c] != sep for c in cols)]
    marked_cols = [c for c in cols if any(grid[r][c] != sep for r in rows)]
    if not marked_rows or not marked_cols:
        # Compact encodings use endpoint markers on the outermost lines.
        if len(rows) == 2:
            return [[next(grid[r][c] for r in rows for c in cols if grid[r][c] != sep)]]
        raise ValueError('no lattice markers')

    result = []
    for i in range(len(marked_rows) - 1):
        row = []
        r0, r1 = marked_rows[i], marked_rows[i + 1]
        for j in range(len(marked_cols) - 1):
            c0, c1 = marked_cols[j], marked_cols[j + 1]
            corners = [grid[r][c] for r in (r0, r1) for c in (c0, c1)]
            if corners[0] != sep and all(v == corners[0] for v in corners):
                value = corners[0]
            else:
                value = grid[(r0 + r1) // 2][(c0 + c1) // 2]
            row.append(value)
        result.append(row)
    return result
